"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["8843"],{2500(e,n,a){a.r(n),a.d(n,{metadata:()=>t,default:()=>h,frontMatter:()=>s,contentTitle:()=>o,toc:()=>d,assets:()=>l});var t=JSON.parse('{"id":"networks/vxlan-and-modern-l2","title":"VXLAN & Modern Layer 2","description":"Traditional VLANs (802.1Q) were designed for the scale and topology assumptions of 1990s-2000s campus networks. Modern datacenters and cloud environments outgrew several of VLAN\'s fundamental limits, motivating VXLAN \u2014 an overlay technology that has become the dominant modern approach to large-scale Layer 2 segmentation.","source":"@site/docs/networks/18-vxlan-and-modern-l2.md","sourceDirName":"networks","slug":"/networks/vxlan-and-modern-l2","permalink":"/Mindstack/docs/networks/vxlan-and-modern-l2","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":18,"frontMatter":{"title":"VXLAN & Modern Layer 2","sidebar_label":"VXLAN & Modern L2","sidebar_position":18},"sidebar":"networkSidebar","previous":{"title":"Layer 2 Troubleshooting","permalink":"/Mindstack/docs/networks/layer2-troubleshooting"},"next":{"title":"Wireless Layer 2","permalink":"/Mindstack/docs/networks/wireless-layer2"}}'),r=a(4848),i=a(8453);let s={title:"VXLAN & Modern Layer 2",sidebar_label:"VXLAN & Modern L2",sidebar_position:18},o="VXLAN & Modern Layer 2",l={},d=[{value:"Why VLANs Stopped Being Enough",id:"why-vlans-stopped-being-enough",level:2},{value:"The Overlay Networking Concept",id:"the-overlay-networking-concept",level:2},{value:"VXLAN \u2014 Virtual Extensible LAN",id:"vxlan--virtual-extensible-lan",level:2},{value:"How VXLAN Solves the Original VLAN Problems",id:"how-vxlan-solves-the-original-vlan-problems",level:2},{value:"EVPN \u2014 The Modern Control Plane for VXLAN",id:"evpn--the-modern-control-plane-for-vxlan",level:2},{value:"VXLAN in Practice \u2014 Datacenter Spine-Leaf Architecture",id:"vxlan-in-practice--datacenter-spine-leaf-architecture",level:2},{value:"Other Modern Layer 2 Overlay Concepts (Brief Mention)",id:"other-modern-layer-2-overlay-concepts-brief-mention",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let n={code:"code",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(n.header,{children:(0,r.jsx)(n.h1,{id:"vxlan--modern-layer-2",children:"VXLAN & Modern Layer 2"})}),"\n",(0,r.jsx)(n.p,{children:"Traditional VLANs (802.1Q) were designed for the scale and topology assumptions of 1990s-2000s campus networks. Modern datacenters and cloud environments outgrew several of VLAN's fundamental limits, motivating VXLAN \u2014 an overlay technology that has become the dominant modern approach to large-scale Layer 2 segmentation."}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"why-vlans-stopped-being-enough",children:"Why VLANs Stopped Being Enough"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Problem 1 \u2014 VLAN ID space is too small:\n  802.1Q's 12-bit VLAN ID field allows only 4094 usable VLANs (see\n  VLANs). A large multi-tenant cloud/datacenter environment \u2014 think\n  thousands of customers, each potentially needing multiple isolated\n  segments \u2014 can exhaust this space entirely.\n\nProblem 2 \u2014 VLANs don't span Layer 3 boundaries naturally:\n  Classic VLANs are fundamentally a Layer 2 construct, trunked between\n  switches via 802.1Q. Extending a single VLAN/broadcast domain across\n  a routed Layer 3 network (e.g. between two separate datacenters, or\n  across a large Layer 3 \"spine-leaf\" fabric \u2014 see Switching\n  Fundamentals) isn't something classic 802.1Q was designed to do.\n\nProblem 3 \u2014 Spanning Tree's blocking wastes capacity at scale:\n  Large topologies with many redundant Layer 2 links suffer from STP's\n  fundamental approach of BLOCKING redundant paths rather than using\n  them all simultaneously (see Spanning Tree Protocol) \u2014 at datacenter\n  scale, with hundreds of links, this becomes a serious capacity and\n  design constraint, not just an inconvenience.\n\nProblem 4 \u2014 Multi-tenancy and overlapping address spaces:\n  Cloud providers need to give DIFFERENT customers (tenants) their own\n  isolated Layer 2/Layer 3 environments \u2014 potentially with OVERLAPPING\n  private IP ranges between completely unrelated customers \u2014 something\n  classic VLANs alone have no clean mechanism to support at scale.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"the-overlay-networking-concept",children:"The Overlay Networking Concept"}),"\n",(0,r.jsxs)(n.p,{children:["VXLAN's core idea: build a ",(0,r.jsx)(n.strong,{children:"virtual Layer 2 network on top of (overlaid on) a real Layer 3 network"}),", by encapsulating Layer 2 Ethernet frames inside Layer 3 UDP packets."]}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"Underlay  \u2014 the actual, physical Layer 3 IP network (routers/switches\n            doing normal IP routing \u2014 simple, robust, well-understood,\n            highly scalable using standard routing protocols)\n\nOverlay   \u2014 a virtual network built ON TOP of the underlay, where\n            endpoints believe they're on the same Layer 2 segment,\n            even though the actual underlying packets are being\n            routed normally across the Layer 3 underlay between them\n\nThis separation is powerful: the underlay can use simple, well-proven,\nhighly scalable Layer 3 routing (no STP blocking problem at all \u2014 every\nlink can be actively used via normal equal-cost routing) while the\noverlay provides the Layer 2 adjacency illusion that some applications\nand legacy systems still expect.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"vxlan--virtual-extensible-lan",children:"VXLAN \u2014 Virtual Extensible LAN"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"VXLAN (RFC 7348, originally developed by Cisco, Arista, VMware, and\nothers, finalized ~2014) encapsulates an entire Ethernet frame inside\na UDP packet, allowing that frame to be routed across a normal Layer 3\nIP network as if it were ordinary IP traffic \u2014 while the two endpoints\non either end believe they're directly Layer-2-adjacent.\n\nVXLAN Encapsulation structure:\n\u250C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u252C\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2510\n\u2502 Outer Eth\u2502 Outer IP \u2502 Outer UDP\u2502 VXLAN Header   \u2502 Original Ethernet\u2502\n\u2502 Header   \u2502 Header   \u2502 Header   \u2502 (8 bytes,      \u2502 Frame (the       \u2502\n\u2502          \u2502          \u2502 (dest    \u2502  includes 24-  \u2502  original L2     \u2502\n\u2502          \u2502          \u2502  port    \u2502  bit VNI)      \u2502  payload being   \u2502\n\u2502          \u2502          \u2502  4789)   \u2502                \u2502  carried)        \u2502\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2534\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2518\n\nKey improvement \u2014 the VNI (VXLAN Network Identifier) is 24 BITS,\nproviding up to ~16 MILLION possible segments \u2014 compare to 802.1Q's\n12-bit VLAN ID giving only ~4094. This single change resolves Problem 1\nabove (VLAN ID exhaustion) by several orders of magnitude.\n\nVTEP (VXLAN Tunnel Endpoint) \u2014 the device (typically a switch, router,\n  or hypervisor virtual switch) that performs the actual encapsulation/\n  decapsulation between the \"real\" Ethernet frame and its VXLAN-wrapped\n  form for transport across the Layer 3 underlay.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"how-vxlan-solves-the-original-vlan-problems",children:"How VXLAN Solves the Original VLAN Problems"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"\u2713 VNI space (24-bit, ~16M) vastly exceeds VLAN ID space (12-bit, ~4094)\n  \u2014 solves multi-tenant/cloud-scale segmentation exhaustion\n\n\u2713 Because the actual transport is normal Layer 3 IP routing, VXLAN\n  overlays can span ACROSS routed Layer 3 boundaries naturally \u2014\n  extending a \"Layer 2\" segment between datacenters, or across a\n  spine-leaf fabric, becomes simply routing UDP packets \u2014 no special\n  Layer 2 extension technology required\n\n\u2713 Because the underlay is pure Layer 3 routing, there's no STP\n  blocking problem at all in the underlay \u2014 standard equal-cost\n  multi-path (ECMP) routing actively uses ALL available links\n  simultaneously, rather than blocking redundant ones\n\n\u2713 Multi-tenancy with overlapping address spaces becomes manageable \u2014\n  different tenants' overlapping private IPs are isolated within\n  their own VNI, invisible to and unaffected by other tenants sharing\n  the same physical underlay infrastructure\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"evpn--the-modern-control-plane-for-vxlan",children:"EVPN \u2014 The Modern Control Plane for VXLAN"}),"\n",(0,r.jsx)(n.p,{children:'VXLAN alone defines only the DATA PLANE encapsulation (how frames are wrapped and transported) \u2014 it doesn\'t, by itself, define how VTEPs learn about each other or how MAC/IP reachability information is distributed across the network. Early VXLAN deployments relied on "flood and learn" (conceptually similar to classic switch MAC learning, but flooding across the Layer 3 underlay via multicast) \u2014 functional, but inefficient at scale.'}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"EVPN (Ethernet VPN, RFC 7432 and related) provides a proper CONTROL\nPLANE for VXLAN, using BGP (see BGP Fundamentals) as the protocol to\nproactively advertise and distribute MAC address and IP reachability\ninformation between VTEPs \u2014 replacing inefficient flood-and-learn\nwith a more deliberate, scalable, BGP-based learning mechanism,\nsimilar in spirit to how a routing protocol proactively shares\nreachability information rather than relying purely on broadcast-based\ndiscovery.\n\nEVPN + VXLAN together is the dominant modern architecture for large-\nscale datacenter fabrics and is increasingly used by service providers\nfor next-generation Layer 2/Layer 3 VPN services, effectively becoming\na modern, more flexible and scalable successor to many use cases that\nwere previously addressed by MPLS L2VPN/L3VPN techniques (see MPLS).\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"vxlan-in-practice--datacenter-spine-leaf-architecture",children:"VXLAN in Practice \u2014 Datacenter Spine-Leaf Architecture"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"                [Spine 1]      [Spine 2]\n                  /    \\         /    \\\n                 /      \\       /      \\\n            [Leaf A]   [Leaf B]   [Leaf C]   \u2190 VTEPs live here\n               \u2502           \u2502           \u2502\n            [Server]    [Server]    [Server]\n\n- Spine switches: pure Layer 3 routing, no VXLAN awareness needed,\n  simply route IP traffic between leaves using ECMP across ALL\n  available spine uplinks simultaneously (no STP blocking at all)\n- Leaf switches: act as VTEPs, encapsulating/decapsulating VXLAN\n  traffic for directly-connected servers, presenting those servers\n  with what looks like normal Layer 2 connectivity to other servers\n  anywhere in the fabric, regardless of which physical leaf they're\n  actually connected to\n- This architecture allows a virtual machine to be migrated from a\n  server under Leaf A to a server under Leaf C while keeping the SAME\n  IP address and remaining in the SAME logical Layer 2 segment (VNI)\n  \u2014 essential for modern virtualization/cloud workload mobility\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"other-modern-layer-2-overlay-concepts-brief-mention",children:"Other Modern Layer 2 Overlay Concepts (Brief Mention)"}),"\n",(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{children:"GENEVE \u2014 a newer, more extensible encapsulation format (similar goal\n  to VXLAN) designed with a flexible, extensible header to accommodate\n  future metadata needs without requiring a new protocol \u2014 increasingly\n  used in some SDN/cloud platforms (see SDN Fundamentals) as an\n  alternative or complement to VXLAN.\n\nNVGRE \u2014 an earlier Microsoft-backed alternative to VXLAN using GRE\n  encapsulation instead of UDP \u2014 saw some adoption but VXLAN became\n  the dominant industry standard.\n"})}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:'Don\'t think of VXLAN as "replacing" IP routing \u2014 it runs ON TOP of normal IP routing in the underlay; the underlay design (often a simple, highly scalable spine-leaf with standard routing protocols like BGP or OSPF) is just as important as the VXLAN overlay configuration itself.'}),"\n",(0,r.jsx)(n.li,{children:'When troubleshooting VXLAN environments, remember there are effectively two separate "networks" to debug: the underlay (can the VTEPs even reach each other via normal IP routing?) and the overlay (is the VXLAN encapsulation/VNI configuration correct?) \u2014 always verify underlay connectivity FIRST.'}),"\n",(0,r.jsx)(n.li,{children:"EVPN's BGP-based control plane means many BGP troubleshooting skills (see BGP Fundamentals) transfer directly to troubleshooting modern VXLAN/EVPN fabrics \u2014 this is a deliberate design choice reusing well-understood, battle-tested routing protocol mechanics rather than inventing an entirely new control plane from scratch."}),"\n"]}),"\n",(0,r.jsx)(n.hr,{}),"\n",(0,r.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,r.jsxs)(n.ul,{children:["\n",(0,r.jsx)(n.li,{children:"VXLAN was created because classic 802.1Q VLANs hit real scaling limits (4094 VLAN ceiling, inability to natively span Layer 3 boundaries, STP's wasteful link-blocking at scale) in modern datacenter and multi-tenant cloud environments."}),"\n",(0,r.jsx)(n.li,{children:"VXLAN encapsulates entire Ethernet frames inside UDP/IP packets, creating a Layer 2 overlay on top of a pure Layer 3 underlay \u2014 VTEPs perform the encapsulation/decapsulation."}),"\n",(0,r.jsx)(n.li,{children:"The 24-bit VNI provides roughly 16 million possible segments, vastly exceeding 802.1Q's ~4094 VLAN limit."}),"\n",(0,r.jsx)(n.li,{children:"EVPN provides a proper BGP-based control plane for VXLAN, replacing inefficient flood-and-learn with proactive, scalable MAC/IP reachability advertisement."}),"\n",(0,r.jsx)(n.li,{children:"The dominant modern datacenter pattern is a spine-leaf physical topology with pure Layer 3 routing in the underlay (no STP blocking) and VXLAN/EVPN providing the Layer 2 overlay illusion needed for workload mobility and multi-tenancy."}),"\n"]})]})}function h(e={}){let{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},8453(e,n,a){a.d(n,{R:()=>s,x:()=>o});var t=a(6540);let r={},i=t.createContext(r);function s(e){let n=t.useContext(i);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),t.createElement(i.Provider,{value:n},e.children)}}}]);